import React, { useState, useEffect } from 'react';
import classes from './Modal.module.scss';

const ModalUnsubscribed = ({ onClose }) => {
    const [isVisible, setIsVisible] = useState(true);
    const [isClosing, setIsClosing] = useState(false);

    useEffect(() => {
        const timer = setTimeout(() => {
            setIsClosing(true); // Запускаем анимацию закрытия
        }, 3000); // Исчезнет через 3 секунды

        return () => clearTimeout(timer); // Очистка таймера при размонтировании компонента
    }, []);

    const handleAnimationEnd = () => {
        if (isClosing) {
            onClose(); // Закрываем модальное окно после завершения анимации
        }
    };

    return (
        isVisible ? (
            <div
                className={`${classes.modal} ${isClosing ? classes.modalFadeOut : ''}`}
                onAnimationEnd={handleAnimationEnd}
            >
                <h2 className={classes.modalTitle}>Вы отписались от услуги</h2>
            </div>
        ) : null
    );
};

export default ModalUnsubscribed;
